def gen(rng):
    alpha = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    def word(a, b):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(a, b)))
    def sp(lo, hi):
        return ' ' * rng.randint(lo, hi)
    def fill(target, wmin, wmax, smin, smax):
        parts, size = [], 0
        while True:
            w = word(wmin, wmax)
            s = sp(smin, smax)
            if size + len(w) + len(s) > target:
                break
            parts.append(w + s)
            size += len(w) + len(s)
        return ''.join(parts)
    tests = ['hello', 'a b', 'Oracle India', '  leading and trailing  ', 'x    y     z', ' a ', 'one two three four five six seven', 'z', '          q']
    for _ in range(16):
        k = rng.randint(1, 8)
        s = sp(0, 2) + ''.join(word(1, 6) + sp(1, 3) for _ in range(k - 1)) + word(1, 6) + sp(0, 2)
        tests.append(s)
    tests.append('a' * 100000)
    tests.append(' '.join(word(1, 1) for _ in range(50000)))
    tests.append(fill(100000, 1, 10, 1, 3))
    tests.append('b' + ' ' * 99998 + 'c')
    return tests
